mapper.select:
SELECT id AS chunk_id, kb_id, doc_id, content, metadata::text AS metadata, embedding <=> #{vectorLiteral}::vector AS distance, ROW_NUMBER() OVER (ORDER BY embedding <=> #{vectorLiteral}::vector) AS rank FROM chunk_bge_m3 WHERE
AND metadata->>'sourceName' = #{sourceName}
AND metadata->>'sourceType' = #{sourceType}
AND lower(regexp_replace(trim(COALESCE(metadata->>'contentPath', '')), '\s+', ' ', 'g')) LIKE CONCAT(REPLACE(REPLACE(REPLACE(#{contentPathPrefix}, '\', '\\'), '%', '\%'), '_', '\_'), '%') ESCAPE '\'
ORDER BY embedding <=> #{vectorLiteral}::vector LIMIT #{limit}

SELECT chunk.id AS chunk_id, chunk.kb_id, chunk.doc_id, chunk.content, chunk.metadata::text AS metadata, chunk.embedding <=> #{vectorLiteral}::vector AS distance, ROW_NUMBER() OVER (ORDER BY chunk.embedding <=> #{vectorLiteral}::vector) AS rank FROM chunk_bge_m3 chunk JOIN document_asset_chunk relation ON relation.chunk_id = chunk.id AND relation.chunk_document_id = chunk.doc_id JOIN document_asset asset ON asset.asset_id = relation.asset_id AND asset.document_id = relation.asset_document_id WHERE
AND asset.asset_type = 'PDF_PAGE_TEXT' AND asset.status = 'READY' AND chunk.embedding IS NOT NULL
AND chunk.metadata->>'sourceName' = #{sourceName}
AND chunk.metadata->>'sourceType' = #{sourceType}
AND lower(regexp_replace(trim(COALESCE(chunk.metadata->>'contentPath', '')), '\s+', ' ', 'g')) LIKE CONCAT(REPLACE(REPLACE(REPLACE(#{contentPathPrefix}, '\', '\\'), '%', '\%'), '_', '\_'), '%') ESCAPE '\'
ORDER BY chunk.embedding <=> #{vectorLiteral}::vector LIMIT #{limit}

SELECT chunk.id AS chunk_id, chunk.kb_id, chunk.doc_id, chunk.content, jsonb_set( COALESCE(chunk.metadata, '{}'::jsonb), '{asset}', jsonb_build_object( 'id', asset.asset_id, 'type', asset.asset_type, 'locator', asset.locator ), true )::text AS metadata, chunk.embedding <=> #{vectorLiteral}::vector AS distance, ROW_NUMBER() OVER ( ORDER BY chunk.embedding <=> #{vectorLiteral}::vector, asset.asset_key ASC, asset.asset_id ASC ) AS rank FROM chunk_bge_m3 chunk JOIN document_asset_chunk relation ON relation.chunk_id = chunk.id AND relation.chunk_document_id = chunk.doc_id JOIN document_asset asset ON asset.asset_id = relation.asset_id AND asset.document_id = relation.asset_document_id WHERE
AND asset.asset_type = 'TABLE' AND asset.status = 'READY' AND chunk.embedding IS NOT NULL
AND chunk.metadata->>'sourceName' = #{sourceName}
AND chunk.metadata->>'sourceType' = #{sourceType}
AND lower(regexp_replace(trim(COALESCE(chunk.metadata->>'contentPath', '')), '\s+', ' ', 'g')) LIKE CONCAT(REPLACE(REPLACE(REPLACE(#{contentPathPrefix}, '\', '\\'), '%', '\%'), '_', '\_'), '%') ESCAPE '\'
ORDER BY chunk.embedding <=> #{vectorLiteral}::vector, asset.asset_key ASC, asset.asset_id ASC LIMIT #{limit}

SELECT id AS chunk_id, kb_id, doc_id, content, metadata::text AS metadata, embedding <=> #{vectorLiteral}::vector AS distance, ROW_NUMBER() OVER (ORDER BY embedding <=> #{vectorLiteral}::vector, created_at ASC, id ASC) AS rank FROM chunk_bge_m3 WHERE
AND lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g')) = #{normalizedTitle}
AND metadata->>'sourceName' = #{sourceName}
AND metadata->>'sourceType' = #{sourceType}
AND lower(regexp_replace(trim(COALESCE(metadata->>'contentPath', '')), '\s+', ' ', 'g')) LIKE CONCAT(REPLACE(REPLACE(REPLACE(#{contentPathPrefix}, '\', '\\'), '%', '\%'), '_', '\_'), '%') ESCAPE '\'
ORDER BY embedding <=> #{vectorLiteral}::vector, created_at ASC, id ASC LIMIT #{limit}

SELECT chunk_id, kb_id, doc_id, content, metadata, distance, rank FROM ( SELECT id AS chunk_id, kb_id, doc_id, content, metadata::text AS metadata, 1::double precision AS distance, ROW_NUMBER() OVER ( ORDER BY ABS(char_length(normalized_title) - char_length(#{normalizedTitle})) ASC, char_length(normalized_title) ASC, created_at ASC, id ASC ) AS rank FROM ( SELECT id, kb_id, doc_id, content, metadata, created_at, lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g')) AS normalized_title FROM chunk_bge_m3 WHERE
AND metadata->>'sourceName' = #{sourceName}
AND metadata->>'sourceType' = #{sourceType}
AND lower(regexp_replace(trim(COALESCE(metadata->>'contentPath', '')), '\s+', ' ', 'g')) LIKE CONCAT(REPLACE(REPLACE(REPLACE(#{contentPathPrefix}, '\', '\\'), '%', '\%'), '_', '\_'), '%') ESCAPE '\'
) t WHERE normalized_title LIKE #{containsPattern} ) ranked ORDER BY rank ASC LIMIT #{limit}

SELECT chunk_id, kb_id, doc_id, content, metadata, distance, rank FROM ( SELECT id AS chunk_id, kb_id, doc_id, content, metadata::text AS metadata, 2::double precision AS distance, ROW_NUMBER() OVER ( ORDER BY keyword_hit_count DESC, keyword_length_sum DESC, ABS(char_length(normalized_title) - #{queryLength}) ASC, char_length(normalized_title) ASC, created_at ASC, id ASC ) AS rank FROM ( SELECT id, kb_id, doc_id, content, metadata, created_at, lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g')) AS normalized_title, ( SELECT COUNT(*) FROM ( SELECT DISTINCT keyword FROM (
SELECT #{keyword} AS keyword
) keyword_list WHERE lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g')) LIKE CONCAT('%', keyword, '%') ) hit_keywords ) AS keyword_hit_count, ( SELECT COALESCE(SUM(char_length(keyword)), 0) FROM ( SELECT DISTINCT keyword FROM (
SELECT #{keyword} AS keyword
) keyword_list WHERE lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g')) LIKE CONCAT('%', keyword, '%') ) hit_keywords ) AS keyword_length_sum FROM chunk_bge_m3 WHERE
) t WHERE keyword_hit_count > 0 ) ranked ORDER BY rank ASC LIMIT #{limit}

SELECT chunk_id, kb_id, doc_id, content, metadata, distance, rank FROM ( SELECT id AS chunk_id, kb_id, doc_id, content, metadata::text AS metadata, 2::double precision AS distance, ROW_NUMBER() OVER ( ORDER BY keyword_hit_count DESC, keyword_length_sum DESC, ABS(char_length(normalized_title) - #{queryLength}) ASC, char_length(normalized_title) ASC, created_at ASC, id ASC ) AS rank FROM ( SELECT id, kb_id, doc_id, content, metadata, created_at, lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g')) AS normalized_title, ( SELECT COUNT(*) FROM ( SELECT DISTINCT keyword FROM (
SELECT #{keyword} AS keyword
) keyword_list WHERE lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g')) LIKE CONCAT('%', keyword, '%') ) hit_keywords ) AS keyword_hit_count, ( SELECT COALESCE(SUM(char_length(keyword)), 0) FROM ( SELECT DISTINCT keyword FROM (
SELECT #{keyword} AS keyword
) keyword_list WHERE lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g')) LIKE CONCAT('%', keyword, '%') ) hit_keywords ) AS keyword_length_sum FROM chunk_bge_m3 WHERE
AND metadata->>'sourceName' = #{sourceName}
AND metadata->>'sourceType' = #{sourceType}
AND lower(regexp_replace(trim(COALESCE(metadata->>'contentPath', '')), '\s+', ' ', 'g')) LIKE CONCAT(REPLACE(REPLACE(REPLACE(#{contentPathPrefix}, '\', '\\'), '%', '\%'), '_', '\_'), '%') ESCAPE '\'
) t WHERE keyword_hit_count > 0 ) ranked ORDER BY rank ASC LIMIT #{limit}

SELECT id AS chunk_id, kb_id, doc_id, content, metadata::text AS metadata, NULL::double precision AS distance, ROW_NUMBER() OVER ( ORDER BY title_bm25_vector <&> bm25_catalog.to_bm25query( 'public.idx_chunk_bge_m3_title_bm25'::regclass, #{queryVector}::bm25_catalog.bm25vector ), created_at ASC, id ASC ) AS rank FROM chunk_bge_m3 WHERE
AND title_bm25_vector IS NOT NULL AND bm25_index_version = #{indexVersion}
AND metadata->>'sourceName' = #{sourceName}
AND metadata->>'sourceType' = #{sourceType}
AND lower(regexp_replace(trim(COALESCE(metadata->>'contentPath', '')), '\s+', ' ', 'g')) LIKE CONCAT(REPLACE(REPLACE(REPLACE(#{contentPathPrefix}, '\', '\\'), '%', '\%'), '_', '\_'), '%') ESCAPE '\'
ORDER BY title_bm25_vector <&> bm25_catalog.to_bm25query( 'public.idx_chunk_bge_m3_title_bm25'::regclass, #{queryVector}::bm25_catalog.bm25vector ), created_at ASC, id ASC LIMIT #{limit}

SELECT id AS chunk_id, kb_id, doc_id, content, metadata::text AS metadata, (1 - similarity(lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g')), CAST(#{normalizedTitle} AS text)))::double precision AS distance, ROW_NUMBER() OVER ( ORDER BY similarity(lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g')), CAST(#{normalizedTitle} AS text)) DESC, ABS(char_length(lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g'))) - char_length(CAST(#{normalizedTitle} AS text))) ASC, created_at ASC, id ASC ) AS rank FROM chunk_bge_m3 WHERE
AND similarity(lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g')), CAST(#{normalizedTitle} AS text)) >= #{minScore}
AND metadata->>'sourceName' = #{sourceName}
AND metadata->>'sourceType' = #{sourceType}
AND lower(regexp_replace(trim(COALESCE(metadata->>'contentPath', '')), '\s+', ' ', 'g')) LIKE CONCAT(REPLACE(REPLACE(REPLACE(#{contentPathPrefix}, '\', '\\'), '%', '\%'), '_', '\_'), '%') ESCAPE '\'
ORDER BY similarity(lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g')), CAST(#{normalizedTitle} AS text)) DESC, ABS(char_length(lower(regexp_replace(trim(COALESCE(metadata->>'retrievableTitle', metadata->>'title')), '\s+', ' ', 'g'))) - char_length(CAST(#{normalizedTitle} AS text))) ASC, created_at ASC, id ASC LIMIT #{limit}

SELECT id AS chunk_id, kb_id, doc_id, content, metadata::text AS metadata, NULL::double precision AS distance, ROW_NUMBER() OVER ( ORDER BY content_bm25_vector <&> bm25_catalog.to_bm25query( 'public.idx_chunk_bge_m3_content_bm25'::regclass, #{queryVector}::bm25_catalog.bm25vector ), created_at ASC, id ASC ) AS rank FROM chunk_bge_m3 WHERE
AND content_bm25_vector IS NOT NULL AND bm25_index_version = #{indexVersion}
AND metadata->>'sourceName' = #{sourceName}
AND metadata->>'sourceType' = #{sourceType}
AND lower(regexp_replace(trim(COALESCE(metadata->>'contentPath', '')), '\s+', ' ', 'g')) LIKE CONCAT(REPLACE(REPLACE(REPLACE(#{contentPathPrefix}, '\', '\\'), '%', '\%'), '_', '\_'), '%') ESCAPE '\'
ORDER BY content_bm25_vector <&> bm25_catalog.to_bm25query( 'public.idx_chunk_bge_m3_content_bm25'::regclass, #{queryVector}::bm25_catalog.bm25vector ), created_at ASC, id ASC LIMIT #{limit}
